DO $$ DECLARE a int; b int; c int; d int; e int; f int; BEGIN
  SELECT count(*) INTO a FROM alu_series WHERE provider_id = 'b542df87-fe61-55cd-b21e-a2015f032ab1';
  SELECT count(*) INTO b FROM alu_profiles WHERE provider_id = 'b542df87-fe61-55cd-b21e-a2015f032ab1';
  SELECT count(*) INTO c FROM alu_series_profiles sp JOIN alu_series s ON s.id = sp.series_id WHERE s.provider_id = 'b542df87-fe61-55cd-b21e-a2015f032ab1';
  SELECT count(*) INTO d FROM alu_series_types st JOIN alu_series s ON s.id = st.series_id WHERE s.provider_id = 'b542df87-fe61-55cd-b21e-a2015f032ab1';
  SELECT count(*) INTO e FROM alu_kg_prices WHERE provider_id = 'b542df87-fe61-55cd-b21e-a2015f032ab1';
  SELECT count(*) INTO f FROM alu_profiles WHERE provider_id = 'b542df87-fe61-55cd-b21e-a2015f032ab1' AND image_path IS NOT NULL;
  IF a <> 7 OR b <> 247 OR c <> 247 OR d <> 12 OR e <> 8 OR f <> 247 THEN
    RAISE EXCEPTION 'count mismatch: series % profiles % links % types % prices % images %', a, b, c, d, e, f; END IF;
END $$;
SELECT f.name family, s.name series, count(sp.id) profiles FROM alu_series s JOIN alu_series_families f ON f.id = s.series_family_id LEFT JOIN alu_series_profiles sp ON sp.series_id = s.id WHERE s.provider_id = 'b542df87-fe61-55cd-b21e-a2015f032ab1' GROUP BY f.name, f.sort_order, s.name ORDER BY f.sort_order, s.name;
COMMIT;
